import datetime, re

access_token = venmo_login['access_token']

# fetch all pages of sent payment requests (approved only where possible)
page_index = 0
page_limit = 20
all_reqs = []
while True:
    resp = apis.venmo.show_sent_payment_requests(access_token=access_token, status='approved', page_index=page_index, page_limit=page_limit)
    # assume resp is list
    if not resp:
        break
    all_reqs.extend(resp)
    page_index += 1

print('approved_sent_payment_requests_count', len(all_reqs))
# filter for receiver name containing Cory
cory_reqs = []
for r in all_reqs:
    recv_name = (r.get('receiver',{}) or {}).get('name','')
    if 'cory' in recv_name.lower():
        cory_reqs.append(r)

print('cory_matching_count', len(cory_reqs))
# show top few by created_at

def parse_dt(s):
    try:
        return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return None

for r in sorted(cory_reqs, key=lambda x: parse_dt(x.get('created_at')) or datetime.datetime.min, reverse=True)[:5]:
    print({
        'payment_request_id': r.get('payment_request_id'),
        'created_at': r.get('created_at'),
        'approved_at': r.get('approved_at'),
        'amount': r.get('amount'),
        'receiver': r.get('receiver')
    })

